package net.officefloor.hq.app.setting;

/**
 * The settings of a sheet being saved, each null when it is left as it is: the clerk limit with two decimals,
 * "" for no limit, the floor with two decimals, the terms as a whole number of days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" for none, and the period numbering from-date as yyyy-MM-dd, "" for off, and the cap, the proof threshold and the note threshold, each with two decimals, "" for none, and the grace days as a whole number of days, "" for off, and the entry date as yyyy-MM-dd, "" for off.
 * {@code gradeTerms} are the terms of a grade's own being saved, as a whole number of days, by grade (a grade left out is left as it is).
 * {@code gradeGrace} are the grace days of a grade being saved, as a whole number of days, "" for none, by grade (a grade left out is left as it is).
 * {@code gradeProof} are the proof thresholds of a grade being saved, with two decimals, "" for none (the sheet's is in force), by grade (a grade left out is left as it is).
 * {@code perms} are the roles each action is permitted to being saved, by action in {@link Settings#PERM_ACTIONS} order, as a comma separated list, "" for the standing rule.
 * {@code pot} is the pot being saved, with two decimals, "" for none (not dated).
 * {@code parent} is the id of the parent sheet being saved, "" for none (not dated).
 * {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on being saved (not dated).
 * {@code alertThreshold} is the alert threshold being saved, with two decimals, "" for off (not dated).
 * {@code rounding} is the rounding mode being saved, half-up or half-even, "" for none (dated).
 * {@code reviewThreshold} is the review threshold being saved, with two decimals, "" for none (dated).
 * {@code from} is the from-date given for a dated setting, by setting key (a key left out is saved from the sheet's today, and audited without one).
 */
public record SheetSettings(String sheetId, String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom, String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.SortedMap<String, String> gradeTerms, java.util.SortedMap<String, String> gradeGrace, java.util.Map<String, java.time.LocalDate> from,
        java.util.Map<String, String> perms, java.util.SortedMap<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold) {
}
package net.officefloor.hq.app.setting;

/** The body of the settings being saved, as typed: the clerk limit (blank: no limit) and the floor, the terms and the late percent (each null or blank: left as it is), and the policy date (null: left as it is; blank: none, so the sheet's today), and the period numbering from-date (null: left as it is; blank: off), and the cap, the proof threshold and the note threshold (each null: left as it is; blank: none), and the grace days (null: left as it is; blank: off), and the entry date (null: left as it is; blank: off, so the sheet's today), and the terms of a grade's own, by grade (each left out, null or blank: left as it is), and the grace days of a grade, by grade (each left out or null: left as it is; blank: none), and the from-date (yyyy-mm-dd) each dated setting saved is recorded from, by setting key (left out or blank: the sheet's today), and the roles each action is permitted to, by action, as a comma separated list (left out or null: left as it is; blank: the standing rule), and the proof threshold of a grade, by grade (each left out or null: left as it is; blank: none, so the sheet's), and the pot (null: left as it is; blank: none), and the parent sheet's id (null: left as it is; blank: none), and the fiscal year start month (null or blank: left as it is), and the alert threshold (null: left as it is; blank: off), and the rounding mode (null: left as it is; blank: none, so the policy date decides), and the review threshold (null: left as it is; blank: none). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String cap, String proofThreshold, String graceDays, String noteThreshold, String entryDate,
        java.util.Map<String, String> gradeTerms, java.util.Map<String, String> gradeGrace, java.util.Map<String, String> from, java.util.Map<String, String> perms,
        java.util.Map<String, String> gradeProof, String pot, String parent, String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold) {
}
package net.officefloor.hq.app.setting;

/** The sheet's settings as the screen sees them, each dated one as it is in force on the sheet's today: the clerk limit with two decimals, "" when there is none, the floor with two decimals, the terms in days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" when there is none (the sheet's today is), and the period numbering from-date as yyyy-MM-dd, "" when it is off, and the terms in force for each grade, in days (its own, or the sheet's terms when it has none), and the cap with two decimals, "" when there is none. {@code dated} is every value recorded for each dated setting, by setting key, by from-date. {@code perms} is the roles each action is permitted to, by action, as a comma separated list, "" for the standing rule. {@code graceDays} is the grace days, "" when they are off. {@code entryDate} is the entry date as yyyy-MM-dd, "" when it is off. {@code pot} is the pot with two decimals, "" when there is none. {@code parent} is the parent sheet's id, "" when there is none. {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on. {@code alertThreshold} is the alert threshold with two decimals, "" when alerts are off. */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, java.util.List<Settings.DatedValue>> dated,
        java.util.Map<String, String> perms, String graceDays, String entryDate, String pot, String parent, String fiscalStartMonth, String alertThreshold) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId, Settings settings, Sheets sheets,
            ObjectResponse<SettingsResponse> response) {
        String sheet = sheetId.trim();
        LocalDate today = sheets.today(sheet);
        response.send(new SettingsResponse(settings.current(sheet, Settings.CLERK_LIMIT),
                settings.floor(sheet, today).setScale(2).toPlainString(), Integer.toString(settings.terms(sheet, today)),
                settings.latePct(sheet, today).setScale(2).toPlainString(), settings.get(sheet, Settings.POLICY_DATE),
                settings.get(sheet, Settings.PERIOD_NUMBERING_FROM), gradeTerms(settings, sheet, today),
                settings.current(sheet, Settings.CAP), dated(settings, sheet), perms(settings, sheet),
                settings.get(sheet, Settings.GRACE_DAYS), settings.get(sheet, Settings.ENTRY_DATE),
                settings.get(sheet, Settings.POT), settings.parent(sheet),
                Integer.toString(settings.fiscalStartMonth(sheet)), settings.get(sheet, Settings.ALERT_THRESHOLD)));
    }

    private static Map<String, String> gradeTerms(Settings settings, String sheet, LocalDate today) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : Settings.GRADES) {
            terms.put(grade, Integer.toString(settings.terms(sheet, grade, today)));
        }
        return terms;
    }

    private static Map<String, String> perms(Settings settings, String sheet) {
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : Settings.PERM_ACTIONS) {
            perms.put(action, settings.perm(sheet, action));
        }
        return perms;
    }

    private static Map<String, List<Settings.DatedValue>> dated(Settings settings, String sheet) {
        Map<String, List<Settings.DatedValue>> dated = new LinkedHashMap<>();
        for (String key : Settings.DATED) {
            dated.put(key, settings.history(sheet, key));
        }
        return dated;
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplySettings {
    // A dated setting is recorded from its from-date, else from the sheet's today, keeping the values recorded from other dates.
    public void apply(@Val SheetSettings settings, Settings store, Sheets sheets) {
        LocalDate today = sheets.today(settings.sheetId());
        if (settings.clerkLimit() != null) {
            dated(settings, store, today, Settings.CLERK_LIMIT, settings.clerkLimit());
        }
        if (settings.floor() != null) {
            dated(settings, store, today, Settings.FLOOR, settings.floor());
        }
        if (settings.terms() != null) {
            dated(settings, store, today, Settings.TERMS, settings.terms());
        }
        settings.gradeTerms().forEach((grade, days) -> dated(settings, store, today, Settings.gradeTermsKey(grade), days));
        if (settings.latePct() != null) {
            dated(settings, store, today, Settings.LATE_PCT, settings.latePct());
        }
        if (settings.policyDate() != null) {
            store.set(settings.sheetId(), Settings.POLICY_DATE, settings.policyDate());
        }
        if (settings.periodNumberingFrom() != null) {
            store.set(settings.sheetId(), Settings.PERIOD_NUMBERING_FROM, settings.periodNumberingFrom());
        }
        if (settings.cap() != null) {
            dated(settings, store, today, Settings.CAP, settings.cap());
        }
        if (settings.proofThreshold() != null) {
            dated(settings, store, today, Settings.PROOF_THRESHOLD, settings.proofThreshold());
        }
        settings.gradeProof().forEach((grade, amount) -> dated(settings, store, today, Settings.gradeProofKey(grade), amount));
        if (settings.noteThreshold() != null) {
            dated(settings, store, today, Settings.NOTE_THRESHOLD, settings.noteThreshold());
        }
        if (settings.graceDays() != null) {
            store.set(settings.sheetId(), Settings.GRACE_DAYS, settings.graceDays());
        }
        settings.gradeGrace().forEach((grade, days) -> dated(settings, store, today, Settings.gradeGraceKey(grade), days));
        if (settings.entryDate() != null) {
            store.set(settings.sheetId(), Settings.ENTRY_DATE, settings.entryDate());
        }
        settings.perms().forEach((action, roles) -> store.set(settings.sheetId(), Settings.permKey(action), roles));
        if (settings.pot() != null) {
            store.set(settings.sheetId(), Settings.POT, settings.pot());
        }
        if (settings.alertThreshold() != null) {
            store.set(settings.sheetId(), Settings.ALERT_THRESHOLD, settings.alertThreshold());
        }
        if (settings.parent() != null) {
            store.set(settings.sheetId(), Settings.PARENT, settings.parent());
        }
        if (settings.fiscalStartMonth() != null) {
            store.set(settings.sheetId(), Settings.FISCAL_START_MONTH, settings.fiscalStartMonth());
        }
        if (settings.rounding() != null) {
            dated(settings, store, today, Settings.ROUNDING, settings.rounding());
        }
        if (settings.reviewThreshold() != null) {
            dated(settings, store, today, Settings.REVIEW_THRESHOLD, settings.reviewThreshold());
        }
    }

    private static void dated(SheetSettings settings, Settings store, LocalDate today, String key, String value) {
        store.set(settings.sheetId(), key, settings.from().getOrDefault(key, today), value);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditSettingChanged {
    // One line per setting saved: the clerk limit, then the floor, then the terms, then each grade's own terms by grade, then the late percent, then the policy date, then the period numbering from-date, then the cap, then the proof threshold, then each grade's proof threshold by grade, then the note threshold, then the grace days, then each grade's grace days by grade, then the entry date, then each action's permitted roles, in the matrix's order, then the pot, then the parent, then the fiscal year start month, then the alert threshold, then the rounding mode, then the review threshold. A dated setting saved with a from-date ends with from=<date>.
    public void audit(@Val SheetSettings settings, ServerHttpConnection connection, Audit audit) {
        if (settings.clerkLimit() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.CLERK_LIMIT, "value=" + settings.clerkLimit(), from(settings, Settings.CLERK_LIMIT)));
        }
        if (settings.floor() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.FLOOR, "value=" + settings.floor(), from(settings, Settings.FLOOR)));
        }
        if (settings.terms() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.TERMS, "value=" + settings.terms(), from(settings, Settings.TERMS)));
        }
        settings.gradeTerms().forEach((grade, days) -> audit.record(dated(settings, connection,
                "key=" + Settings.gradeTermsKey(grade), "value=" + days, from(settings, Settings.gradeTermsKey(grade)))));
        if (settings.latePct() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.LATE_PCT, "value=" + settings.latePct(), from(settings, Settings.LATE_PCT)));
        }
        if (settings.policyDate() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.POLICY_DATE, "value=" + settings.policyDate()));
        }
        if (settings.periodNumberingFrom() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.PERIOD_NUMBERING_FROM, "value=" + settings.periodNumberingFrom()));
        }
        if (settings.cap() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.CAP, "value=" + settings.cap(), from(settings, Settings.CAP)));
        }
        if (settings.proofThreshold() != null) {
            audit.record(dated(settings, connection, "key=" + Settings.PROOF_THRESHOLD, "value=" + settings.proofThreshold(),
                    from(settings, Settings.PROOF_THRESHOLD)));
        }
        settings.gradeProof().forEach((grade, amount) -> audit.record(dated(settings, connection,
                "key=" + Settings.gradeProofKey(grade), "value=" + amount, from(settings, Settings.gradeProofKey(grade)))));
        if (settings.noteThreshold() != null) {
            audit.record(dated(settings, connection, "key=" + Settings.NOTE_THRESHOLD, "value=" + settings.noteThreshold(),
                    from(settings, Settings.NOTE_THRESHOLD)));
        }
        if (settings.graceDays() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.GRACE_DAYS, "value=" + settings.graceDays()));
        }
        settings.gradeGrace().forEach((grade, days) -> audit.record(dated(settings, connection,
                "key=" + Settings.gradeGraceKey(grade), "value=" + days, from(settings, Settings.gradeGraceKey(grade)))));
        if (settings.entryDate() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.ENTRY_DATE, "value=" + settings.entryDate()));
        }
        settings.perms().forEach((action, roles) -> audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(),
                Audit.user(connection), "key=" + Settings.permKey(action), "value=" + roles)));
        if (settings.pot() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.POT, "value=" + settings.pot()));
        }
        if (settings.parent() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.PARENT, "value=" + settings.parent()));
        }
        if (settings.fiscalStartMonth() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.FISCAL_START_MONTH, "value=" + settings.fiscalStartMonth()));
        }
        if (settings.alertThreshold() != null) {
            audit.record(Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection),
                    "key=" + Settings.ALERT_THRESHOLD, "value=" + settings.alertThreshold()));
        }
        if (settings.rounding() != null) {
            audit.record(dated(settings, connection,
                    "key=" + Settings.ROUNDING, "value=" + settings.rounding(), from(settings, Settings.ROUNDING)));
        }
        if (settings.reviewThreshold() != null) {
            audit.record(dated(settings, connection, "key=" + Settings.REVIEW_THRESHOLD, "value=" + settings.reviewThreshold(),
                    from(settings, Settings.REVIEW_THRESHOLD)));
        }
    }

    private static String from(SheetSettings settings, String key) {
        java.time.LocalDate from = settings.from().get(key);
        return from == null ? null : "from=" + from;
    }

    /** A dated setting's line: its key and value, then its from-date when one was given. */
    private static String dated(SheetSettings settings, ServerHttpConnection connection, String key, String value, String from) {
        String line = Audit.line("SETTING_CHANGED", settings.sheetId(), Audit.user(connection), key, value);
        return from == null ? line : line + " " + from;
    }
}
            noteThreshold = twoDecimals(noteThreshold);
        }
        String reviewThreshold = body == null || body.reviewThreshold() == null ? null : body.reviewThreshold().trim();
        if (reviewThreshold != null && !reviewThreshold.isEmpty()) {
            if (!AMOUNT.matcher(reviewThreshold).matches()) {
                throw new InvalidSettingException("The review threshold must be an amount of 0.00 or more, with up to two decimals.");
